//! The quotient basis: the vectors that express every quotient in Dynark,
//! derived once per circuit from the Groth16 prover key, with no trapdoor
//! (Section "Keeping the same prover key as Groth16" of the paper).
use crate::poly::convolution::convolution_f_g;
use ark_ec::{pairing::Pairing, AffineRepr};
use ark_ff::{Field, Zero};
use ark_poly::{EvaluationDomain, GeneralEvaluationDomain};
use ark_serialize::{CanonicalDeserialize, CanonicalSerialize};
use ark_std::vec::Vec;
use rayon::prelude::*;

/// The quotient basis over a domain of size `n`, generated by `omega`.
#[derive(Clone, Debug, PartialEq, CanonicalSerialize, CanonicalDeserialize)]
pub struct QuotientBasis<E: Pairing> {
    /// The truncated Lagrange basis in G1, scaled by `Z_H(tau) / delta` (the
    /// paper's `\bar{\ell}`). It is the iDFT of the prover key's `h_query`
    /// padded with the identity.
    pub ell_bar: Vec<E::G1>,
    /// The diagonal quotients `phi_{i,i}` in G1 (the paper's `\mathfrak{p}`):
    /// `diag = -(sum of w) * ell_bar - convolution(w, ell_bar)`.
    pub diag: Vec<E::G1>,
    /// The paper's `\mathfrak{w}`: `w[i] = omega^i / (n * (1 - omega^i))` for
    /// `i > 0`, and `w[0] = 0`.
    pub w: Vec<E::ScalarField>,
    /// The paper's `\mathfrak{w}'`: `w_prime[i] = w[-i mod n]`, i.e. `w`
    /// reversed modulo `n`.
    pub w_prime: Vec<E::ScalarField>,
    /// The DFT of `w`.
    pub w_dft: Vec<E::ScalarField>,
    /// The DFT of `w_prime`.
    pub w_prime_dft: Vec<E::ScalarField>,
}

impl<E: Pairing> QuotientBasis<E> {
    /// Derives the basis from the prover key's `h_query`, the elements
    /// `tau^i * Z_H(tau) / delta` in G1, for `i < n - 1`.
    pub fn new(
        domain: &GeneralEvaluationDomain<E::ScalarField>,
        h_query: &[E::G1Affine],
    ) -> Self {
        let domain_size = domain.size();
        debug_assert!((domain_size % 2) == 0);

        let mut tau_powers_truncated = h_query.to_vec();
        tau_powers_truncated.push(E::G1Affine::zero());
        let tau_powers_truncated: Vec<<E as Pairing>::G1> = tau_powers_truncated
            .par_iter()
            .map(|x| (*x).into())
            .collect();

        let ell_bar = domain.ifft(&tau_powers_truncated);

        let domain_gen: E::ScalarField = domain.group_gen();

        let one_over_n = E::ScalarField::from(domain_size as u64).inverse().unwrap();
        let w: Vec<E::ScalarField> = (0..domain_size)
            .scan(domain_gen.inverse().unwrap(), |state, _| {
                *state *= domain_gen;
                Some(*state)
            })
            .map(|gi| {
                let denom = E::ScalarField::ONE - gi;
                if denom.is_zero() {
                    E::ScalarField::zero()
                } else {
                    gi * denom.inverse().unwrap() * one_over_n
                }
            })
            .collect();

        let w_prime: Vec<E::ScalarField> = (0..domain_size)
            .into_par_iter()
            .map(|i| {
                if i == 0 {
                    E::ScalarField::zero()
                } else {
                    w[domain_size - i]
                }
            })
            .collect();

        let coeff1 = w.iter().fold(E::ScalarField::zero(), |acc, x| acc + x);
        let conv: Vec<E::G1> = convolution_f_g::<E>(&w, &ell_bar);

        let diag: Vec<E::G1> = ell_bar
            .par_iter()
            .zip(conv.par_iter())
            .map(|(x, y)| -(*x * coeff1 + *y))
            .collect();

        debug_assert_eq!(ell_bar.len(), domain_size);
        debug_assert_eq!(w.len(), domain_size);
        debug_assert_eq!(w_prime.len(), domain_size);
        debug_assert_eq!(diag.len(), domain_size);

        let w_dft = domain.fft(&w);
        let w_prime_dft = domain.fft(&w_prime);

        Self {
            ell_bar,
            diag,
            w,
            w_prime,
            w_dft,
            w_prime_dft,
        }
    }
}
